SELECT count(*) AS n,COALESCE(sum(CASE WHEN length(row_sha)=64 AND row_sha NOT GLOB '*[^0-9a-f]*' THEN 1 ELSE 0 END),0) AS valid_n,length(CAST(COALESCE(group_concat(row_sha,''),'') AS BLOB)) AS concat_bytes,lower(hex(crypto_sha256(CAST('casepath-journal-bytes-v1:set:'||COALESCE(group_concat(row_sha,''),'') AS BLOB)))) AS root FROM (SELECT lower(hex(crypto_sha256(CAST('casepath-journal-bytes-v1:row:'||(CASE typeof(session_id) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(session_id AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(session_id AS BLOB),X''))))||(CASE typeof(loop_id) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(loop_id AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(loop_id AS BLOB),X''))))||(CASE typeof(sequence) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(sequence AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(sequence AS BLOB),X''))))||(CASE typeof(idempotency_key) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(idempotency_key AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(idempotency_key AS BLOB),X''))))||(CASE typeof(command_sha256) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(command_sha256 AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(command_sha256 AS BLOB),X''))))||(CASE typeof(event_sha256) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(event_sha256 AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(event_sha256 AS BLOB),X''))))||(CASE typeof(event_json) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(event_json AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(event_json AS BLOB),X''))))||(CASE typeof(created_at) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(created_at AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(created_at AS BLOB),X'')))) AS BLOB)))) AS row_sha FROM claim_loop_events WHERE session_id=? ORDER BY loop_id,sequence LIMIT ?)